<body>

    <div class="container">

        <h1>🎵 Late-Night Beat Sketcher</h1>



        <div class="controls">

            <button id="playBtn">▶ Play</button>

            <div class="tempo-control">

                <label for="tempoSlider">BPM:</label>

                <input type="range" id="tempoSlider" min="40" max="200" value="120">

                <div class="tempo-display" id="tempoDisplay">120</div>

            </div>

        </div>



        <div class="grid-wrapper">

            <div class="beat-numbers">

                <div class="beat-label">Track</div>

                <div class="beat-number downbeat">1–4</div>

                <div class="beat-number">5–8</div>

                <div class="beat-number">9–12</div>

                <div class="beat-number">13–16</div>

            </div>

            <div class="grid-container" id="grid"></div>

        </div>



        <div class="info">

            Click grid cells to toggle sounds. Use Clear/Random buttons to manage rows. Press Play to hear the pattern.

        </div>

    </div>



    <script>

        // Web Audio context

        const audioContext = new (window.AudioContext || window.webkitAudioContext)();



        // Beat state

        let isPlaying = false;

        let tempo = 120;

        let nextNoteTime = 0.0;

        let scheduleAheadTime = 0.1;

        let lookAhead = 25.0;

        let scheduledSteps = new Set();

        let timerID = null;



        // Track configuration: 4 tracks, 16 steps each

        const tracks = [

            { name: 'Kick', color: '#ff006e', synthFn: synthKick },

            { name: 'Snare', color: '#00d4ff', synthFn: synthSnare },

            { name: 'HiHat', color: '#ffd60a', synthFn: synthHiHat },

            { name: 'Perc', color: '#8338ec', synthFn: synthPerc }

        ];



        // Grid state: 4 tracks × 16 steps

        const grid = Array(4).fill().map(() => Array(16).fill(false));



        // ============ Sound Synthesis Functions ============



        function synthKick(time) {

            const osc = audioContext.createOscillator();

            const gain = audioContext.createGain();



            osc.connect(gain);

            gain.connect(audioContext.destination);



            osc.frequency.setValueAtTime(150, time);

            osc.frequency.exponentialRampToValueAtTime(0.01, time + 0.5);



            gain.gain.setValueAtTime(1, time);

            gain.gain.exponentialRampToValueAtTime(0.01, time + 0.5);



            osc.start(time);

            osc.stop(time + 0.5);

        }



        function synthSnare(time) {

            const noise = audioContext.createBufferSource();

            const buffer = audioContext.createBuffer(1, audioContext.sampleRate * 0.2, audioContext.sampleRate);

            const data = buffer.getChannelData(0);

            for (let i = 0; i < buffer.length; i++) {

                data[i] = Math.random() * 2 - 1;

            }

            noise.buffer = buffer;



            const gain = audioContext.createGain();

            noise.connect(gain);

            gain.connect(audioContext.destination);



            gain.gain.setValueAtTime(0.8, time);

            gain.gain.exponentialRampToValueAtTime(0.01, time + 0.2);



            noise.start(time);

            noise.stop(time + 0.2);

        }



        function synthHiHat(time) {

            const noise = audioContext.createBufferSource();

            const buffer = audioContext.createBuffer(1, audioContext.sampleRate * 0.1, audioContext.sampleRate);

            const data = buffer.getChannelData(0);

            for (let i = 0; i < buffer.length; i++) {

                data[i] = Math.random() * 2 - 1;

            }

            noise.buffer = buffer;



            const filter = audioContext.createBiquadFilter();

            filter.type = 'highpass';

            filter.frequency.setValueAtTime(8000, time);



            const gain = audioContext.createGain();

            noise.connect(filter);

            filter.connect(gain);

            gain.connect(audioContext.destination);



            gain.gain.setValueAtTime(0.5, time);

            gain.gain.exponentialRampToValueAtTime(0.01, time + 0.1);



            noise.start(time);

            noise.stop(time + 0.1);

        }



        function synthPerc(time) {

            const osc = audioContext.createOscillator();

            const gain = audioContext.createGain();



            osc.connect(gain);

            gain.connect(audioContext.destination);



            osc.frequency.setValueAtTime(300, time);

            osc.frequency.exponentialRampToValueAtTime(50, time + 0.15);



            gain.gain.setValueAtValue(0.7, time);

            gain.gain.exponentialRampToValueAtTime(0.01, time + 0.15);



            osc.start(time);

            osc.stop(time + 0.15);

        }



        // ============ Scheduling ============



        function scheduleNote(step) {

            for (let track = 0; track < tracks.length; track++) {

                if (grid[track][step]) {

                    const time = audioContext.currentTime + (nextNoteTime - audioContext.currentTime);

                    tracks[track].synthFn(time);

                }

            }

        }



        function nextNote() {

            const secondsPerBeat = 60.0 / tempo;

            nextNoteTime += 0.25 * secondsPerBeat;

        }



        function scheduler() {

            while (nextNoteTime < audioContext.currentTime + scheduleAheadTime) {

                const stepNum = scheduledSteps.size % 16;

                scheduleNote(stepNum);

                scheduledSteps.add(nextNoteTime);

                nextNote();

            }

        }



        function timerWorker() {

            scheduler();

        }



        function startPlay() {

            isPlaying = true;

            scheduledSteps = new Set();

            nextNoteTime = audioContext.currentTime;

            timerID = setInterval(timerWorker, lookAhead);

        }



        function stopPlay() {

            isPlaying = false;

            clearInterval(timerID);

            scheduledSteps = new Set();

            document.querySelectorAll('.step').forEach(btn => {

                btn.classList.remove('playing');

            });

        }



        // ============ Grid Utilities ============



        function clearTrack(trackIdx) {

            grid[trackIdx].fill(false);

            updateTrackUI(trackIdx);

        }



        function randomizeTrack(trackIdx) {

            for (let step = 0; step < 16; step++) {

                grid[trackIdx][step] = Math.random() > 0.5;

            }

            updateTrackUI(trackIdx);

        }



        function updateTrackUI(trackIdx) {

            document.querySelectorAll(`[data-track="${trackIdx}"]`).forEach(btn => {

                const step = parseInt(btn.dataset.step);

                if (grid[trackIdx][step]) {

                    btn.classList.add('active');

                } else {

                    btn.classList.remove('active');

                }

            });

        }



        // ============ UI ============



        const playBtn = document.getElementById('playBtn');

        const tempoSlider = document.getElementById('tempoSlider');

        const tempoDisplay = document.getElementById('tempoDisplay');

        const gridContainer = document.getElementById('grid');



        playBtn.addEventListener('click', () => {

            if (isPlaying) {

                stopPlay();

                playBtn.textContent = '▶ Play';

                playBtn.classList.remove('playing');

            } else {

                startPlay();

                playBtn.textContent = '⏹ Stop';

                playBtn.classList.add('playing');

            }

        });



        tempoSlider.addEventListener('input', (e) => {

            tempo = parseInt(e.target.value);

            tempoDisplay.textContent = tempo;

        });



        // Build grid UI

        tracks.forEach((track, trackIdx) => {

            const trackRowDiv = document.createElement('div');

            trackRowDiv.className = 'track-row';



            // Header with label and buttons

            const headerDiv = document.createElement('div');

            headerDiv.className = 'track-header';



            const labelDiv = document.createElement('div');

            labelDiv.className = 'track-label';

            labelDiv.textContent = track.name;

            headerDiv.appendChild(labelDiv);



            const buttonsDiv = document.createElement('div');

            buttonsDiv.className = 'track-buttons';



            const clearBtn = document.createElement('button');

            clearBtn.className = 'mini-btn';

            clearBtn.textContent = 'Clear';

            clearBtn.addEventListener('click', () => clearTrack(trackIdx));

            buttonsDiv.appendChild(clearBtn);



            const randomBtn = document.createElement('button');

            randomBtn.className = 'mini-btn';

            randomBtn.textContent = 'Random';

            randomBtn.addEventListener('click', () => randomizeTrack(trackIdx));

            buttonsDiv.appendChild(randomBtn);



            headerDiv.appendChild(buttonsDiv);

            trackRowDiv.appendChild(headerDiv);



            // Steps grid

            const trackDiv = document.createElement('div');

            trackDiv.className = 'track';



            for (let col = 0; col < 4; col++) {

                const beatColumn = document.createElement('div');

                beatColumn.className = 'beat-column';

                if (col === 0) {

                    beatColumn.classList.add('downbeat');

                }



                for (let row = 0; row < 4; row++) {

                    const step = col * 4 + row;

                    const stepBtn = document.createElement('div');

                    stepBtn.className = 'step';

                    stepBtn.dataset.track = trackIdx;

                    stepBtn.dataset.step = step;



                    stepBtn.addEventListener('click', () => {

                        grid[trackIdx][step] = !grid[trackIdx][step];

                        stepBtn.classList.toggle('active');

                    });



                    beatColumn.appendChild(stepBtn);

                }



                trackDiv.appendChild(beatColumn);

            }



            trackRowDiv.appendChild(trackDiv);

            gridContainer.appendChild(trackRowDiv);

        });



        // Update playhead display smoothly

        function updatePlayhead() {

            if (!isPlaying) return;



            const secondsPerBeat = 60.0 / tempo;

            const elapsedBeats = (nextNoteTime - audioContext.currentTime) / secondsPerBeat;

            const currentStep = Math.floor(elapsedBeats / 4) % 16;



            document.querySelectorAll('.step').forEach(btn => {

                btn.classList.remove('playing');

                if (parseInt(btn.dataset.step) === currentStep) {

                    btn.classList.add('playing');

                }

            });

        }



        setInterval(updatePlayhead, 16);

    </script>

</body>

</html>

Key additions:

Numbered beat columns: Top header shows "1–4", "5–8", "9–12", "13–16" with downbeat highlighting
Downbeat accents: Column 1 (steps 0–3) has a bold left border and styled background to visually stand out
Per-track controls: Each instrument row has Clear and Random buttons that only affect that row
Better layout: Reorganized grid so 4 steps are grouped together per visual column, making it easier to read measures at a glance

The grid is now much easier to scan and the buttons give you quick ways to build patterns without manually clicking every cell!

