        ];



        // Grid state: 4 tracks × 16 steps

        const grid = Array(4).fill().map(() => Array(16).fill(false));



        // ============ Storage ============



        const STORAGE_KEY = 'beatSketcherPattern';

        const TEMPO_KEY = 'beatSketcherTempo';



        function savePattern() {

            try {

                const data = {

                    grid: grid,

                    tempo: tempo,

                    timestamp: new Date().toLocaleString()

                };

                localStorage.setItem(STORAGE_KEY, JSON.stringify(data));

                localStorage.setItem(TEMPO_KEY, tempo);

                showStatus('✓ Pattern saved!', true);

            } catch (e) {

                showStatus('✗ Save failed', false);

            }

        }



        function loadPattern() {

            try {

                const data = localStorage.getItem(STORAGE_KEY);

                if (!data) {

                    showStatus('✗ No saved pattern', false);

                    return;

                }

                const parsed = JSON.parse(data);

                for (let t = 0; t < 4; t++) {

                    for (let s = 0; s < 16; s++) {

                        grid[t][s] = parsed.grid[t][s];

                    }

                }

                tempo = parsed.tempo || 120;

                tempoSlider.value = tempo;

                tempoDisplay.textContent = tempo;

                updateAllTrackUI();

                showStatus(`✓ Loaded: ${parsed.timestamp}`, true);

            } catch (e) {

                showStatus('✗ Load failed', false);

            }

        }



        function clearPattern() {

            try {

                if (confirm('Clear saved pattern? This cannot be undone.')) {

                    localStorage.removeItem(STORAGE_KEY);

                    localStorage.removeItem(TEMPO_KEY);

                    showStatus('✓ Pattern cleared', true);

                }

            } catch (e) {

                showStatus('✗ Clear failed', false);

            }

        }



